FUNCTION handleDeleteSensor(request, sensor_id):
    // REQ-2-016; Preconditions: available persistence. REQUIRE admin or RETURN 401/403.
    IF sensor_id <= 0 OR absent THEN RETURN 404. BEGIN TRANSACTION.
    IF reading, policy, or alert exists THEN ROLLBACK; RETURN 409 under REQ-2-008. END IF
    DELETE sensor; COMMIT; RETURN 204.
    // A repeat returns 404. On error rollback preserves the sensor and every relation.

FUNCTION handleDeleteThreshold(request, sensor_id):
    // REQ-2-020; Preconditions: available persistence. REQUIRE owner/admin or RETURN 401/403.
    IF sensor_id <= 0 OR sensor/policy absent THEN RETURN 404. BEGIN TRANSACTION; DELETE policy only; COMMIT; RETURN 204.
    // REQ-2-009 preserves alerts. Repeat is 404; errors roll back and preserve policy, sensor, readings, alerts.

FUNCTION handleListAlerts(request):
    // REQ-2-026; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    VALIDATE filter enums and pagination or RETURN 422. IF sensor_id supplied and non-positive/absent THEN RETURN 404. END IF
    IF user caller requests another owner's sensor THEN RETURN 403. READ matching owner-visible alerts; order by id and page; RETURN 200.
    // Transaction: none. Postcondition: alerts and every related resource remain unchanged.

FUNCTION handleGetHealth(request):
    // REQ-2-011; Preconditions: none. Authorization: public.
    IF local persistence probe fails THEN RETURN 503. END IF
    RETURN 200 with status = ok.
    // Transaction: none. Postcondition: all persistent state is unchanged.

FUNCTION handleGetReading(request, reading_id):
    // REQ-2-023; Preconditions: available persistence. REQUIRE authenticated caller or RETURN 401.
    IF reading_id <= 0 OR reading absent THEN RETURN 404. IF user caller does not own reading.sensor THEN RETURN 403. END IF
    RETURN 200 with immutable reading.
    // Transaction: none. Postcondition: persistent state is unchanged under REQ-2-003.

FUNCTION handleGetSensor(request, sensor_id):
    // REQ-2-014; Preconditions: persistence is available. REQUIRE authenticated user or admin or RETURN 401.
    IF sensor_id <= 0 OR sensor absent THEN RETURN 404. END IF
    IF caller is user AND caller does not own sensor THEN RETURN 403. END IF
    READ sensor and policy summary; RETURN 200.
    // Transaction: none. Postcondition: persistent sensor, reading, policy, and alert state is unchanged.

FUNCTION handleGetLatestReading(request, sensor_id):
    // REQ-2-024; Preconditions: available persistence. REQUIRE owner/admin or RETURN 401/403.
    IF sensor_id <= 0 OR absent THEN RETURN 404. END IF
    READ greatest captured_at, breaking ties by greatest id; RETURN 200 with reading or null.
    // Transaction: none; postcondition: no persistent state changes.

FUNCTION handleGetTelemetryRange(request, sensor_id):
    // REQ-2-025; Preconditions: available persistence. REQUIRE owner/admin or RETURN 401/403.
    IF sensor_id <= 0 OR absent THEN RETURN 404. VALIDATE required UTC dates and interval under REQ-2-007 or RETURN 422.
    READ readings in [from,to), calculate count/min/max/average deterministically; RETURN 200.
    // Transaction: none. Postcondition: all persistent telemetry and alert state is unchanged.

FUNCTION handleListReadings(request, sensor_id):
    // REQ-2-022; Preconditions: persistence available. REQUIRE owner/admin or RETURN 401/403.
    IF sensor_id <= 0 OR absent THEN RETURN 404. VALIDATE UTC filters, cursor, and limit; RETURN 422 if invalid.
    IF both dates supplied THEN enforce REQ-2-007 or RETURN 422. END IF
    READ owned readings matching from <= captured_at < to; order by id and page; RETURN 200.
    // Transaction: none; postcondition: readings, policies, and alerts are unchanged.

FUNCTION handleGetThreshold(request, sensor_id):
    // REQ-2-017; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    IF sensor_id <= 0 OR absent THEN RETURN 404. IF user caller is not owner THEN RETURN 403. END IF
    READ active policy, possibly null; RETURN 200.
    // Transaction: none. Postcondition: all persistent state is unchanged.

FUNCTION handlePatchSensor(request, sensor_id):
    // REQ-2-015; Preconditions: JSON and available persistence. REQUIRE admin or RETURN 401/403; REQUIRE JSON media type or RETURN 415.
    IF sensor_id <= 0 OR absent THEN RETURN 404. Parse JSON or RETURN 400; VALIDATE non-empty resulting patch and owner, or RETURN 422.
    BEGIN TRANSACTION; APPLY supplied name/owner fields only; COMMIT; RETURN 200.
    // Identical valid patch is idempotent. On error ROLLBACK; sensor and all telemetry relations remain unchanged.

FUNCTION handlePatchThreshold(request, sensor_id):
    // REQ-2-019; Preconditions: JSON, available persistence, existing sensor and policy. REQUIRE owner/admin or RETURN 401/403.
    IF sensor_id <= 0 OR sensor/policy absent THEN RETURN 404. REQUIRE JSON or RETURN 415; parse or RETURN 400.
    VALIDATE non-empty complete resulting bounds under REQ-2-005 or RETURN 422. BEGIN TRANSACTION; UPDATE bounds only; COMMIT; RETURN 200.
    // Identical payload is idempotent. On rollback sensor, policy, readings, and immutable alerts stay unchanged.

FUNCTION handleCreateReading(request, sensor_id):
    // REQ-2-021; Preconditions: JSON, positive existing sensor, persistence available. REQUIRE owner/admin or RETURN 401/403.
    REQUIRE JSON or RETURN 415; parse or RETURN 400; VALIDATE UTC timestamp and physical range or RETURN 422.
    BEGIN TRANSACTION; lock sensor. IF captured_at already exists THEN ROLLBACK; RETURN 409. END IF
    CREATE immutable reading; evaluate policy; create exactly one alert if breached; COMMIT; RETURN 201 with Location.
    // Non-idempotent. Any error rolls back reading and alert together, leaving all state unchanged.

FUNCTION handleCreateThreshold(request, sensor_id):
